(163, 31, 6, 17, 'PAPEL PRENSA S.A.I.C.F. Y M.', 132, 1, 1, '1185316', '2023-07-19', '2023-09-18', '2023-10-07', '<p class=\"MsoNormal\"><b>Alcance:<o:p></o:p></b></p><p>\r\n\r\n</p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n <li class=\"MsoListParagraph\" style=\"margin-left:0cm;mso-list:l0 level1 lfo1\">Red externa, Whitebox<o:p></o:p></li>\r\n <li class=\"MsoListParagraph\" style=\"margin-left:0cm;mso-list:l0 level1 lfo1\">15 servidores<o:p></o:p></li>\r\n <li class=\"MsoListParagraph\" style=\"margin-left:0cm;mso-list:l0 level1 lfo1\">IPs: 200.89.129.106 y 181.30.100.74<o:p></o:p></li>\r\n <li class=\"MsoListParagraph\" style=\"margin-left:0cm;mso-list:l0 level1 lfo1\">Web: <a href=\"http://www.papelprensa.com.ar/portalclientes\">www.papelprensa.com.ar/portalclientes</a><a href=\"http://www.papelprensa.com.ar/portalclientes\"></a></li></ul><p style=\"margin-left: 0cm;\"><br></p><p style=\"margin-left: 0cm;\">Cliente:&nbsp;Caviglia, Alejandro &lt;acaviglia@papelprensa.com.ar&gt;</p><p style=\"margin-left: 0cm;\">EDC:&nbsp;Romina Barcia &lt;RBarcia@teco.com.ar&gt;</p><p style=\"margin-left: 0cm;\"><b><u>Falta confirmar por completo el alcance</u></b></p><ul style=\"margin-top:0cm\" type=\"disc\">\r\n</ul>', '200.89.129.106\r\n181.30.100.74', 'www.papelprensa.com.ar/portalclientes', 'NUEVO', 1, '2023-07-27 12:40:46', NULL, NULL, NULL, NULL, NULL, 3, 1),
(164, 31, 6, 10, 'I.A.F.A.S. PROV.DE ENTRE RIOS', 133, 1, 1, '1169376 ', '2023-06-08', '2023-08-14', '2023-09-08', '<p>Ejecutivo de cuenta:&nbsp;Ariel Roberto Gamboa &lt;ARGamboa@teco.com.ar&gt;</p><p>Contacto referente tecnico cliente:&nbsp;<span style=\"font-size: 1rem;\">Germán Dachary (</span><a href=\"mailto:gdachary@iafas.gov.ar\" target=\"_blank\" style=\"background-color: rgb(255, 255, 255); font-size: 1rem;\">gdachary@iafas.gov.ar</a><span style=\"font-size: 1rem;\">) - Tel. 0343 - 4201113</span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;margin-bottom:10.0pt;\r\nline-height:115%\">El rango horario para el Pentest debería ser desde las 23hs a\r\nlas 7hs, las tareas más simples de revisión pueden ser en otro horario a\r\nacordar.</p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;margin-bottom:10.0pt;\r\nline-height:115%\"><o:p><br></o:p></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;margin-bottom:10.0pt;\r\nline-height:115%\"><o:p>PENDIENTE: sitio WEB el cliente lo enviara la próxima&nbsp;</o:p><span style=\"font-size: 1rem;\">semana</span><span style=\"font-size: 1rem;\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;margin-bottom:10.0pt;\r\nline-height:115%\"><o:p></o:p></p>', '192.141.20.97  \r\n192.141.20.98\r\n192.141.20.99\r\n192.141.20.100\r\n192.141.20.101\r\n192.141.20.102\r\n192.141.20.103\r\n192.141.20.104\r\n190.228.173.88\r\n190.228.173.89\r\n190.228.173.90\r\n190.228.173.91\r\n190.228.173.92\r\n190.228.173.93\r\n190.228.173.94\r\n190.228.173.95', 'https://servicios.iafas.gov.ar', 'Cerrado', 4, '2023-08-03 16:05:29', 1, NULL, NULL, NULL, '2023-10-09 17:22:34', 3, 1);
